        XCTAssertThrowsError(try Page.factFault.path([:])) { XCTAssertEqual($0 as? PathError, .missing(page: .factFault, param: "kind")) }
    }

    func test_a_path_that_is_no_page_matches_none() {
        XCTAssertNil(Page.match("/zz/zz/zz/zz/zz/zz/zz/zz/zz/zz/zz/zz"))
    }

