            (##"{"at":"at 1","op":"notice","tone":"tone 1"}"##, Fallback.Reason.missing(path: ["text"])),
            (##"{"at":"at 1","op":"notice","text":1,"tone":"tone 1"}"##, Fallback.Reason.wrongType(path: ["text"])),
